import { findContourHoles } from '../../../utilities/contours/index.js';
import { getAnnotation } from '../../annotation/annotationState.js';
import { getSegmentation } from '../getSegmentation.js';
import { extractSegmentPolylines } from './extractSegmentPolylines.js';
import { removeCompleteContourAnnotation } from './removeCompleteContourAnnotation.js';
import { utilities as cornerstoneUtilities } from '@cornerstonejs/core';
const cs3dLogger = cornerstoneUtilities.logger.toolsLog.getLogger('stateManagement.segmentation.utilities.removeContourHoles');
export default function removeContourHoles(segmentationId, segmentIndex) {
    const segmentation = getSegmentation(segmentationId);
    if (!segmentation) {
        cs3dLogger.warn(`Invalid segmentation given ${segmentationId}`);
        return;
    }
    if (!segmentation.representationData.Contour) {
        cs3dLogger.warn(`No contour representation found for segmentation ${segmentationId}`);
        return;
    }
    const polylinesCanvasMap = extractSegmentPolylines(segmentationId, segmentIndex);
    if (!polylinesCanvasMap) {
        cs3dLogger.warn(`Error extracting contour data from segment ${segmentIndex} in segmentation ${segmentationId}`);
        return;
    }
    const keys = Array.from(polylinesCanvasMap?.keys());
    const polylines = keys.map((key) => polylinesCanvasMap.get(key));
    const holeDetectionResults = findContourHoles(polylines);
    if (holeDetectionResults?.length > 0) {
        holeDetectionResults.forEach((hole) => {
            hole.holeIndexes.forEach((index) => {
                const annotation = getAnnotation(keys[index]);
                removeCompleteContourAnnotation(annotation);
            });
        });
    }
}
